                shells.append(sm.groups())
            else: print("fail",s)
        elif s.startswith('couplings:'):
            couplings_line=s[len('couplings:'):].strip()
        i+=1
    universes.append({'id':uid,'type':typ,'shells':shells,'couplings':couplings_line})
